fn parse_and_double(s: Str) -> Result[Int, Str] {
  let n = string.str_to_int(s)?;
  return Ok(n * 2);
}

fn parse_validate_halve(s: Str) -> Result[Int, Str] {
  let n = string.str_to_int(s)?;
  if n <= 10 { return Err("Number must be greater than 10"); }
  return Ok(n / 2);
}

fn main() -> Int {
  match parse_and_double("7") {
    Ok(r) => io.println(string.int_to_str(r)),
    Err(e) => io.println(e),
  };
  match parse_and_double("bad") {
    Ok(r) => io.println(string.int_to_str(r)),
    Err(e) => io.println(e),
  };
  match parse_validate_halve("20") {
    Ok(r) => io.println(string.int_to_str(r)),
    Err(e) => io.println(e),
  };
  match parse_validate_halve("8") {
    Ok(r) => io.println(string.int_to_str(r)),
    Err(e) => io.println(e),
  };
  match parse_validate_halve("abc") {
    Ok(r) => io.println(string.int_to_str(r)),
    Err(e) => io.println(e),
  };
  return 0;
}
